namespace sv_1f8e6d2c7a78408e98d2ff7bf56a1b5c.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Patel"
    };

    private static readonly List<string> TimeSlots = new()
    {
        "9:00 AM",
        "9:30 AM",
        "10:00 AM",
        "10:30 AM",
        "11:00 AM",
        "11:30 AM",
        "1:00 PM",
        "1:30 PM",
        "2:00 PM",
        "2:30 PM",
        "3:00 PM",
        "3:30 PM"
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all time slots regardless of doctor/date
        return Task.FromResult(new List<string>(TimeSlots));
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentModel.Email)] = "Account has outstanding balance";
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(AppointmentModel.PreferredDoctor)] = "Selected doctor does not accept self-pay patients";
        }

        // Reject "10:00 AM" as taken (simulates race condition)
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(AppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(new ValidationResult(errors));
    }
}

public class ValidationResult
{
    public Dictionary<string, string> Errors { get; }
    public bool IsValid => Errors.Count == 0;

    public ValidationResult(Dictionary<string, string> errors)
    {
        Errors = errors;
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_1f8e6d2c7a78408e98d2ff7bf56a1b5c.Services;

public class AppointmentModel
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    [Required(ErrorMessage = "Preferred doctor is required.")]
    public string PreferredDoctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required.")]
    [FutureDate(ErrorMessage = "Date must be in the future.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Time slot is required.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

public class FutureDateAttribute : ValidationAttribute
{
    protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(
        object? value, ValidationContext validationContext)
    {
        if (value is DateOnly date && date <= DateOnly.FromDateTime(DateTime.Today))
        {
            return new System.ComponentModel.DataAnnotations.ValidationResult(ErrorMessage);
        }
        return System.ComponentModel.DataAnnotations.ValidationResult.Success;
    }
}

