+        if (string.IsNullOrWhiteSpace(Model.Email) || !new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email))
+            isValid = false;
+        if (string.IsNullOrWhiteSpace(Model.Phone))
+            isValid = false;
+        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
+            isValid = false;
+
+        if (isValid)
+        {
+            showStep2 = true;
+        }
+        else
+        {
+            // Trigger validation display via EditContext
+            editContext.Validate();
+        }
+    }
+
+    private async Task OnDateChanged()
+    {
+        if (Model.AppointmentDate.HasValue && !string.IsNullOrEmpty(Model.PreferredDoctor))
+        {
+            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
+                Model.PreferredDoctor, Model.AppointmentDate.Value);
+        }
+        availabilityChecked = false;
+    }
+
+    private async Task CheckAvailability()
+    {
+        serverErrors.Clear();
+        availabilityChecked = false;
+
+        // Validate step 2 fields
+        if (string.IsNullOrWhiteSpace(Model.PreferredDoctor) ||
+            !Model.AppointmentDate.HasValue ||
+            string.IsNullOrWhiteSpace(Model.TimeSlot) ||
+            string.IsNullOrWhiteSpace(Model.ReasonForVisit))
+        {
+            return;
+        }
+
+        if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+        {
+            return;
+        }
+
+        if (Model.ReasonForVisit.Length > 500)
+        {
+            return;
+        }
+
+        var result = await AppointmentService.ValidatePatientAsync(
+            Model.Email,
+            Model.InsuranceProvider,
+            Model.PreferredDoctor,
+            Model.TimeSlot);
+
+        if (!result.IsValid)
+        {
+            serverErrors = new Dictionary<string, string>(result.Errors);
+        }
+        else
+        {
+            availabilityChecked = true;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (availabilityChecked)
+        {
+            bookingConfirmed = true;
+        }
+    }
+}
